-- SKAI-1955 (DB-01): columns that name a pupil (student_id...), a class (class_id, target_class_id...) or a
-- placement (source_enrollment_id...) now reference that row pinned to the row's own school:
-- (school_id, <col>) -> students / classes / student_enrollments (school_id, id). A row can no longer name a
-- missing pupil or class, or one from another school.
--
-- Every key is ON DELETE NO ACTION (restrict). Pupils are archived, not deleted, so their history must not
-- vanish or be nulled. The one hard delete in the app, reversing an unchanged import, is refused with a 409
-- (Prisma P2003) if any record already names the pupil. Deleting a school still removes its rows, pupils and
-- classes together in one statement.
--
-- students and student_enrollments gain a unique (school_id, id) as the key target. Keys are added NOT VALID and
-- then validated. For a large production table build each index first with CREATE INDEX CONCURRENTLY under the
-- same name. Rollback: DROP CONSTRAINT "<table>_school_id_<col>_fkey" and DROP INDEX "<table>_school_id_<col>_idx"
-- for the names below, then "students_school_id_id_key" and "student_enrollments_school_id_id_key".
SET lock_timeout = '10s';

CREATE UNIQUE INDEX IF NOT EXISTS "students_school_id_id_key" ON "students"("school_id", "id");
CREATE UNIQUE INDEX IF NOT EXISTS "student_enrollments_school_id_id_key" ON "student_enrollments"("school_id", "id");
CREATE INDEX IF NOT EXISTS "admission_applications_school_id_intake_class_id_idx" ON "admission_applications"("school_id", "intake_class_id");
CREATE INDEX IF NOT EXISTS "attendance_explanations_school_id_student_id_idx" ON "attendance_explanations"("school_id", "student_id");
CREATE INDEX IF NOT EXISTS "online_payment_orders_school_id_student_id_idx" ON "online_payment_orders"("school_id", "student_id");
CREATE INDEX IF NOT EXISTS "financial_adjustments_school_id_student_id_idx" ON "financial_adjustments"("school_id", "student_id");
CREATE INDEX IF NOT EXISTS "intervention_plans_school_id_class_id_idx" ON "intervention_plans"("school_id", "class_id");
CREATE INDEX IF NOT EXISTS "intervention_plans_school_id_student_id_idx" ON "intervention_plans"("school_id", "student_id");
CREATE INDEX IF NOT EXISTS "parent_conversations_school_id_student_id_idx" ON "parent_conversations"("school_id", "student_id");
CREATE INDEX IF NOT EXISTS "trip_invitees_school_id_student_id_idx" ON "trip_invitees"("school_id", "student_id");
CREATE INDEX IF NOT EXISTS "trip_consents_school_id_student_id_idx" ON "trip_consents"("school_id", "student_id");
CREATE INDEX IF NOT EXISTS "family_digests_school_id_class_id_idx" ON "family_digests"("school_id", "class_id");
CREATE INDEX IF NOT EXISTS "family_digest_entries_school_id_student_id_idx" ON "family_digest_entries"("school_id", "student_id");
CREATE INDEX IF NOT EXISTS "mark_scan_cells_school_id_student_id_idx" ON "mark_scan_cells"("school_id", "student_id");
CREATE INDEX IF NOT EXISTS "meeting_bookings_school_id_student_id_idx" ON "meeting_bookings"("school_id", "student_id");
CREATE INDEX IF NOT EXISTS "meeting_actions_school_id_student_id_idx" ON "meeting_actions"("school_id", "student_id");
CREATE INDEX IF NOT EXISTS "portfolio_entries_school_id_class_id_idx" ON "portfolio_entries"("school_id", "class_id");
CREATE INDEX IF NOT EXISTS "emergency_accesses_school_id_student_id_idx" ON "emergency_accesses"("school_id", "student_id");
CREATE INDEX IF NOT EXISTS "care_plans_school_id_student_id_idx" ON "care_plans"("school_id", "student_id");
